def resolve_output_dir(output: str | Path) -> Path:
    path = Path(output).expanduser()
    if not path.is_absolute():
        path = Path.cwd() / path
    return path.resolve()


def init_agent_directory(output_dir: str | Path, force: bool = False, dry_run: bool = False) -> InitAgentResult:
    root = resolve_output_dir(output_dir)

    if root.exists() and not root.is_dir():
        raise ValueError(f"Output path exists and is not a directory: {root}")

    if root.exists() and any(root.iterdir()) and not force:
        raise ValueError(_NON_EMPTY_DIR_MSG)

    files = managed_files()
    created: list[Path] = [root / Path(rel.as_posix()) for rel, _ in files]

    if dry_run:
        return InitAgentResult(output_dir=root, created_files=created, dry_run=True)

    root.mkdir(parents=True, exist_ok=True)
    for rel, content in files:
        path = root / Path(rel.as_posix())
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding="utf-8")

    return InitAgentResult(output_dir=root, created_files=created, dry_run=False)


def managed_relative_paths() -> Iterable[str]:
    for rel, _ in managed_files():
        yield rel.as_posix()
